#!/usr/bin/env node

require('dotenv').config();
const { McpServer } = require('@modelcontextprotocol/sdk/server/mcp.js');
const { StdioServerTransport } = require('@modelcontextprotocol/sdk/server/stdio.js');
const { TavilySearchAPI } = require('./tavily-search.js');
const { tavilyConfig } = require('./config.js');

// 验证API密钥
const apiKey = process.env.TAVILY_API_KEY;
if (!apiKey || apiKey === 'your_api_key_here') {
  console.error('❌ 错误: 请在.env文件中设置有效的TAVILY_API_KEY');
  console.log('📝 提示: 复制.env.example为.env并填入你的API密钥');
  process.exit(1);
}

// 创建Tavily API实例
const tavilyAPI = new TavilySearchAPI(apiKey);

// 创建MCP服务器
const mcpServer = new McpServer({
  name: 'tavily-search',
  version: '1.0.0'
});

// 注册搜索工具
mcpServer.registerTool('search', {
  description: 'Search the web using Tavily AI Search API',
  inputSchema: {
    query: {
      type: 'string',
      description: 'The search query'
    },
    max_results: {
      type: 'number',
      description: 'Maximum number of results to return',
      default: 10
    },
    search_depth: {
      type: 'string',
      description: 'Search depth: basic or advanced',
      enum: ['basic', 'advanced'],
      default: 'basic'
    }
  }
}, async ({ query, max_results, search_depth }) => {
  try {
    console.log(`🔍 搜索查询: ${query} (max_results: ${max_results}, depth: ${search_depth})`);

    const results = await tavilyAPI.search(query, {
      max_results,
      search_depth,
      include_answer: true,
      include_raw_content: false
    });

    // 格式化结果
    let output = `🔍 搜索查询: ${results.query}\n`;
    output += `⏱️  响应时间: ${results.response_time}秒\n`;
    output += `📊 找到 ${results.results.length} 个结果\n\n`;

    if (results.answer) {
      output += `💡 答案:\n${results.answer}\n\n`;
    }

    output += `📄 相关结果:\n`;
    results.results.forEach((result, index) => {
      output += `\n${index + 1}. ${result.title}\n`;
      output += `   🔗 ${result.url}\n`;
      if (result.content) {
        output += `   📝 ${result.content.substring(0, 200)}${result.content.length > 200 ? '...' : ''}\n`;
      }
      output += `   ⭐ 分数: ${result.score}\n`;
    });

    return {
      content: [
        {
          type: 'text',
          text: output
        }
      ]
    };
  } catch (error) {
    console.error('❌ 搜索错误:', error.message);
    return {
      content: [
        {
          type: 'text',
          text: `❌ 搜索失败: ${error.message}`
        }
      ],
      isError: true
    };
  }
});

async function main() {
  try {
    const transport = new StdioServerTransport();
    await mcpServer.connect(transport);
    console.log('🚀 Tavily MCP服务器已启动');
  } catch (error) {
    console.error('❌ 服务器启动失败:', error);
    process.exit(1);
  }
}

main();

